import { Component, input } from '@angular/core';
import { NzImageModule } from 'ng-zorro-antd/image';

/** hrm-image — ảnh có preview (click phóng to), bọc nz-image. */
@Component({
  selector: 'hrm-image',
  imports: [NzImageModule],
  template: `
    <img
      nz-image
      [nzSrc]="src()"
      [nzFallback]="fallback() || null"
      [nzDisablePreview]="!preview()"
      [alt]="alt()"
      [style.width.px]="width()"
      [style.height.px]="height()"
      [style.border-radius]="'var(--radius-lg)'"
      [style.object-fit]="'cover'" />
  `,
  host: { class: 'hrm-image' },
})
export class HrmImage {
  readonly src = input('');
  readonly alt = input('');
  readonly width = input<number | null>(null);
  readonly height = input<number | null>(null);
  readonly preview = input(true);
  /** Ảnh thay thế khi src lỗi/không tải được (data-URI hoặc URL). '' = không có. */
  readonly fallback = input('');
}
